begin;
create or replace function public.project_api_internal(p_route text,p_method text default 'GET',b jsonb default '{}',query jsonb default '{}') returns jsonb language plpgsql security definer set search_path='' as $$
#variable_conflict use_column
declare uid uuid:=auth.uid();parts text[]:=string_to_array(p_route,'/');pid uuid;target uuid;cid uuid;rid uuid;fid uuid;payer uuid;amount bigint;allocated bigint;balance bigint;adj bigint;d date;m date;eff date;s public.project_settings;pol jsonb;bp public.billing_periods;i public.flat_invoices;pay public.payment_submissions;bill public.project_expense_bills;a public.committee_appointments;att public.project_attachments;q public.project_questions;op public.project_operations;li record;rec record;lines jsonb;res jsonb;k text;ref text;kind text;first boolean;c boolean;v text;
begin
 if uid is null then raise exception 'Sign in';end if;if p_method not in ('GET','POST') then raise exception 'Method unavailable';end if;
 if parts[1] in ('appointments','appointment-options') then
 if p_method='GET' then
 if parts[1]='appointment-options' then if not private.staff_role(array['platform']) then raise exception 'Platform appointment administrator only';end if;return jsonb_build_object('projects',(select jsonb_agg(to_jsonb(p) order by p.name) from public.projects p),'residents',coalesce((select jsonb_agg(x) from (select distinct p.id,p.display_name name,f.project_id,j.name project,f.label from public.profiles p cross join public.flats f join public.projects j on j.id=f.project_id where not f.is_test and private.project_relationship(p.id,f.project_id) and (exists(select 1 from public.ownership where user_id=p.id and flat_id=f.id) or exists(select 1 from public.memberships mm where mm.user_id=p.id and mm.flat_id=f.id and mm.status='approved' and mm.move_in<=now() and (mm.move_out is null or mm.move_out>now())))) x),'[]'));end if;
 return coalesce((select jsonb_agg(to_jsonb(a)||jsonb_build_object('name',pr.display_name,'project',pj.name) order by a.appointed_at desc) from public.committee_appointments a join public.profiles pr on pr.id=a.user_id join public.projects pj on pj.id=a.project_id where a.user_id=uid or private.staff_role(array['platform'])),'[]');end if;
 if b->>'action'='invite' then
 if not private.staff_role(array['platform']) then raise exception 'Platform appointment administrator only';end if;pid:=(b->>'projectId')::uuid;payer:=(b->>'userId')::uuid;
 if payer=uid or not private.project_relationship(payer,pid) or b->>'position' not in ('president','vice_president') then raise exception 'Choose another verified owner or resident in this project';end if;
 insert into public.committee_appointments(project_id,user_id,position,status,appointed_by,starts,ends) values(pid,payer,b->>'position','invited',uid,(b->>'starts')::date,(b->>'ends')::date) returning id into target;perform private.project_history_add(pid,'committee.invited',target,'Acceptance and platform activation required');return jsonb_build_object('id',target);end if;
 target:=(b->>'id')::uuid;select * into a from public.committee_appointments where id=target for update;if not found then raise exception 'Appointment unavailable';end if;pid:=a.project_id;perform pg_advisory_xact_lock(hashtextextended(pid::text,17));
 if b->>'action' in ('accept','resign') then
 if a.user_id<>uid or not private.project_relationship(uid,pid) then raise exception 'This appointment belongs to another eligible resident';end if;
 if b->>'action'='accept' and a.status='invited' and a.ends>(now() at time zone 'Asia/Kolkata')::date then update public.committee_appointments set status='accepted',accepted_at=now() where id=target;
 elsif b->>'action'='resign' and a.status='active' then update public.committee_appointments set status='resigned' where id=target;else raise exception 'Invalid appointment transition';end if;
 else
 if not private.staff_role(array['platform']) then raise exception 'Platform appointment administrator only';end if;
 if b->>'action'='activate' then if a.user_id=uid or a.status<>'accepted' or a.accepted_at is null or not private.project_relationship(a.user_id,pid) or a.ends<=(now() at time zone 'Asia/Kolkata')::date then raise exception 'Another eligible resident must accept before activation';end if;update public.committee_appointments set status='revoked' where project_id=pid and status='active' and ends<=(now() at time zone 'Asia/Kolkata')::date;update public.committee_appointments set status='active' where id=target;
 elsif b->>'action'='revoke' then update public.committee_appointments set status='revoked' where id=target;else raise exception 'Unknown appointment action';end if;end if;
 perform private.project_history_add(pid,'committee.'||(b->>'action'),target,'Appointment updated');return jsonb_build_object('ok',true);end if;
 if p_route='my-project' and p_method='GET' then return jsonb_build_object('projects',coalesce((select jsonb_agg(x) from (select distinct f.id flat_id,f.project_id,p.name project,f.label from public.flats f join public.projects p on p.id=f.project_id where not f.is_test and (exists(select 1 from public.ownership where user_id=uid and flat_id=f.id) or exists(select 1 from public.memberships m where m.user_id=uid and m.flat_id=f.id and m.status='approved' and m.move_in<=now() and (m.move_out is null or m.move_out>now())))) x),'[]'),'invitations',public.project_api('appointments'));end if;
 pid:=parts[2]::uuid;if not private.project_relationship(uid,pid) then raise exception 'Verified ownership or residence in this project required';end if;c:=private.project_committee(pid);
 if p_method='GET' then
 if parts[3] is null then return private.project_workspace(pid);end if;
 if parts[3]='accounts' then m:=private.op_month(query->>'month');if not c and not exists(select 1 from public.billing_periods where project_id=pid and month=m and state in ('published','closed')) then raise exception 'Accounts have not been published';end if;return private.project_accounts(pid,m);end if;
 if parts[3]='annual' then if query->>'year' !~ '^\d{4}$' then raise exception 'Use a four-digit year';end if;return jsonb_build_object('projectId',pid,'year',query->>'year','months',coalesce((select jsonb_agg(private.project_accounts(pid,month) order by month) from public.billing_periods where project_id=pid and to_char(month,'YYYY')=query->>'year' and state in ('published','closed')),'[]'));end if;
 if parts[3]='attachments' then
 target:=parts[4]::uuid;select * into att from public.project_attachments where id=target and project_id=pid;
 if not found or att.scan_state<>'clean' or not (c or att.owner_id=uid and not private.bill_attachment(target) or att.visibility='redacted' and exists(select 1 from public.project_expense_bills bb join public.billing_periods pp on pp.project_id=pid and pp.month=bb.period where bb.project_id=pid and bb.redacted_attachment_id=target and bb.status='approved' and pp.state in ('published','closed'))) then raise exception 'Attachment unavailable or awaiting file verification';end if;
 return to_jsonb(att)||jsonb_build_object('data',(select content from private.project_attachment_data where id=target));end if;raise exception 'Project read unavailable';end if;
 -- Serialize every project mutation: prevents competing receipt/credit/bill allocations.
 perform pg_advisory_xact_lock(hashtextextended(pid::text,17));
 select * into s from public.project_settings where project_id=pid for update;pol:=s.policy;
 if parts[3]='attachments' then
 if (select count(*) from public.project_attachments where owner_id=uid and project_id=pid)>=500 then raise exception 'Attachment limit reached';end if;
 v:=b->>'data';if length(v)>2666668 or b->>'mime' not in ('image/jpeg','image/png','application/pdf') or octet_length(decode(v,'base64'))>2000000 then raise exception 'Use a PDF, JPEG or PNG below 2 MB';end if;
 -- Only server-normalized raster images are immediately reviewable. PDF is quarantined.
 if b->>'mime'='image/jpeg' and substring(decode(v,'base64') from 1 for 3)<>decode('ffd8ff','hex') or b->>'mime'='image/png' and substring(decode(v,'base64') from 1 for 8)<>decode('89504e470d0a1a0a','hex') or b->>'mime'='application/pdf' and substring(decode(v,'base64') from 1 for 5)<>convert_to('%PDF-','UTF8') then raise exception 'File format does not match its type';end if;
 target:=gen_random_uuid();insert into public.project_attachments(id,project_id,owner_id,name,mime,object_key,visibility,scan_state) values(target,pid,uid,private.op_text(b->>'name',150),b->>'mime','private-db/'||target,case when c and coalesce((b->>'redacted')::boolean,false) then 'redacted' else 'private' end,'quarantined');insert into private.project_attachment_data values(target,v);return jsonb_build_object('id',target,'name',b->>'name','scan_state','quarantined');end if;
 if parts[3]='payments' then
 target:=(b->>'invoiceId')::uuid;select * into i from public.flat_invoices where id=target and project_id=pid for update;
 if not found or i.payer_id<>uid or not private.published_invoice(i.id) then raise exception 'Only the billed payer may submit payment proof for a published invoice';end if;
 amount:=private.op_amount(b->>'amount',1);k:=private.op_text(b->>'key',100);ref:=private.op_text(b->>'reference',200);perform private.project_own_attachment(pid,nullif(b->>'attachmentId','')::uuid);
 select * into pay from public.payment_submissions where user_id=uid and request_key=k;if found then if pay.invoice_id<>i.id or pay.amount<>amount or pay.reference<>ref then raise exception 'Payment retry differs from original';end if;return to_jsonb(pay);end if;
 insert into public.payment_submissions(project_id,user_id,invoice_id,amount,reference,attachment_id,request_key) values(pid,uid,i.id,amount,ref,nullif(b->>'attachmentId','')::uuid,k) returning id into target;return jsonb_build_object('id',target);end if;
 if parts[3]='questions' then
 if parts[4] is null then if b->>'category' not in ('Billing','Maintenance','Repairs','Water','Power','Lift','Suggestion','General') then raise exception 'Choose a question category';end if;perform private.project_own_attachment(pid,nullif(b->>'attachmentId','')::uuid);
 insert into public.project_questions(project_id,user_id,category,subject,body,visibility,attachment_id,faq_consent) values(pid,uid,b->>'category',private.op_text(b->>'subject',150),private.op_text(b->>'body',3000),case when b->>'visibility'='project' then 'project' else 'private' end,nullif(b->>'attachmentId','')::uuid,coalesce((b->>'faqConsent')::boolean,false)) returning id into target;perform private.project_history_add(pid,'question.created',target,'Question opened');
 else target:=parts[4]::uuid;select * into q from public.project_questions where id=target and project_id=pid for update;if not found or not (c or q.user_id=uid or q.visibility='project') then raise exception 'Question unavailable';end if;
 if b ? 'body' then insert into public.project_replies(project_id,question_id,user_id,body) values(pid,target,uid,private.op_text(b->>'body',3000));end if;
 if b ? 'status' then if b->>'status' not in ('open','in_progress','awaiting_resident','resolved','escalated') or not c and (q.user_id<>uid or b->>'status' not in ('open','escalated')) then raise exception 'Committee status update required';end if;update public.project_questions set status=b->>'status' where id=target;end if;
 if b ? 'assignedTo' then if not c or (nullif(b->>'assignedTo','') is not null and not exists(select 1 from public.committee_appointments ca where ca.project_id=pid and ca.user_id=nullif(b->>'assignedTo','')::uuid and ca.status='active' and ca.starts<=(now() at time zone 'Asia/Kolkata')::date and ca.ends>(now() at time zone 'Asia/Kolkata')::date and private.project_relationship(ca.user_id,pid))) then raise exception 'Choose an active committee member';end if;update public.project_questions set assigned_to=nullif(b->>'assignedTo','')::uuid where id=target;end if;
 perform private.project_history_add(pid,'question.updated',target,coalesce(b->>'status','reply'));end if;return jsonb_build_object('id',target);end if;
 if parts[3]='vote' then target:=(b->>'id')::uuid;select * into op from public.project_operations where id=target and project_id=pid and kind='poll';if not found or nullif(op.payload->>'ends','') is null or (op.payload->>'ends')::timestamptz<=now() or not coalesce(op.payload->'options' ? (b->>'choice'),false) then raise exception 'Poll closed or choice unavailable';end if;insert into public.project_votes values(pid,target,uid,b->>'choice') on conflict(operation_id,user_id) do update set choice=excluded.choice;return jsonb_build_object('ok',true);end if;
 if not c then raise exception 'An active President or Vice President appointment in this project is required';end if;
 if parts[3]='settings' then
 if b->>'action'='liability' then
 fid:=(b->>'flatId')::uuid;payer:=(b->>'payerId')::uuid;if not exists(select 1 from public.flats where id=fid and project_id=pid and not is_test) or not (exists(select 1 from public.ownership where user_id=payer and flat_id=fid) or exists(select 1 from public.memberships mm where mm.flat_id=fid and mm.user_id=payer and mm.status='approved' and mm.move_in<=now() and (mm.move_out is null or mm.move_out>now()))) then raise exception 'Choose this flat and a verified owner or resident of it';end if;
 if nullif(b->>'area','') is not null and ((b->>'area')::numeric<=0 or (b->>'area')::numeric>100000 or not coalesce((b->>'areaVerified')::boolean,false)) then raise exception 'Confirm area against the verified register';end if;
 insert into public.project_flat_liability(flat_id,project_id,payer_id,area,area_verified,opening_due,exemption) values(fid,pid,payer,nullif(b->>'area','')::numeric,coalesce((b->>'areaVerified')::boolean,false),private.op_amount(coalesce(b->>'openingDue','0')),private.op_amount(coalesce(b->>'exemption','0'))) on conflict(flat_id) do update set payer_id=excluded.payer_id,area=excluded.area,area_verified=excluded.area_verified,opening_due=excluded.opening_due,exemption=excluded.exemption;
 else
 if coalesce(b->>'mode','') not in ('fixed','area') or coalesce(jsonb_typeof(b->'categories'),'null')<>'array' or jsonb_array_length(b->'categories')>16 or exists(select 1 from jsonb_array_elements_text(b->'categories') cat where cat not in ('Security','Electricity','Water','Lift AMC','Generator diesel','Generator service','Plumbing','Electrical','Tiles','Cleaning','Pumps','Gardening','Pest control','Insurance','Repairs','Miscellaneous')) or not coalesce((b->>'approved')::boolean,false) then raise exception 'Approve a valid project billing policy and facility categories';end if;
 amount:=private.op_amount(b->>'amount',0,10000000);perform private.op_amount(b->>'dueDay',1,28);perform private.op_amount(coalesce(b->>'special','0'));perform private.op_amount(coalesce(b->>'approvalThreshold','0'));balance:=private.op_amount(coalesce(b->>'openingCash','0'));adj:=private.op_amount(coalesce(b->>'openingReserve','0'));
 if exists(select 1 from public.billing_periods where project_id=pid) and (s.opening_cash<>balance or s.opening_reserve<>adj) then raise exception 'Opening balances cannot change after billing starts';end if;
 update public.project_settings set enabled=coalesce((b->>'enabled')::boolean,false),start_date=(b->>'startDate')::date,opening_cash=balance,opening_reserve=adj,policy=jsonb_build_object('mode',b->>'mode','amount',amount,'dueDay',(b->>'dueDay')::integer,'categories',b->'categories','special',coalesce((b->>'special')::bigint,0),'specialLabel',left(coalesce(b->>'specialLabel','Special assessment'),100),'independentReview',coalesce((b->>'independentReview')::boolean,true),'approvalThreshold',coalesce((b->>'approvalThreshold')::bigint,0),'paymentInstructions',left(coalesce(b->>'paymentInstructions',''),1500),'penaltyEnabled',false) where project_id=pid;
 end if;perform private.project_history_add(pid,'policy.configured',pid,'Prospective settings; existing invoices unchanged');return jsonb_build_object('ok',true);end if;
 if parts[3]='billing' then
 if b->>'action'='draft' then
 m:=private.op_month(b->>'month');if not s.enabled or s.start_date is null or m<date_trunc('month',s.start_date)::date then raise exception 'Approve and activate maintenance policy first';end if;
 select * into bp from public.billing_periods where project_id=pid and month=m;if found then return to_jsonb(bp);end if;
 if not exists(select 1 from public.flats where project_id=pid and not is_test) or exists(select 1 from public.flats f left join public.project_flat_liability fl on fl.flat_id=f.id where f.project_id=pid and not f.is_test and (fl.payer_id is null or pol->>'mode'='area' and (not fl.area_verified or coalesce(fl.area,0)<=0))) then raise exception 'Assign an explicit payer to every registered flat and verify area for area billing';end if;
 first:=not exists(select 1 from public.billing_periods where project_id=pid);insert into public.billing_periods(project_id,month,state) values(pid,m,'draft') returning id into target;
 for li in select fl.*,f.label from public.project_flat_liability fl join public.flats f on f.id=fl.flat_id where fl.project_id=pid and not f.is_test loop
 if not exists(select 1 from public.ownership where user_id=li.payer_id and flat_id=li.flat_id) and not exists(select 1 from public.memberships mm where mm.user_id=li.payer_id and mm.flat_id=li.flat_id and mm.status='approved' and mm.move_in<=now() and (mm.move_out is null or mm.move_out>now())) then raise exception 'A configured payer is no longer eligible; review the flat register';end if;
 amount:=round((pol->>'amount')::numeric*case when pol->>'mode'='area' then li.area else 1 end)::bigint;lines:=jsonb_build_array(jsonb_build_object('label','Maintenance','amount',amount));
 if coalesce((pol->>'special')::bigint,0)>0 then lines:=lines||jsonb_build_array(jsonb_build_object('label',pol->>'specialLabel','amount',(pol->>'special')::bigint));end if;
 if first and li.opening_due>0 then lines:=lines||jsonb_build_array(jsonb_build_object('label','Verified opening dues','amount',li.opening_due));end if;
 if li.exemption>0 then lines:=lines||jsonb_build_array(jsonb_build_object('label','Approved exemption','amount',-least(li.exemption,amount)));end if;
 select sum((ln->>'amount')::bigint) into amount from jsonb_array_elements(lines) ln;
 insert into public.flat_invoices(project_id,period_id,flat_id,payer_id,due_date,lines,amount) values(pid,target,li.flat_id,li.payer_id,m+((pol->>'dueDay')::integer-1),lines,amount);
 end loop;
 else target:=(b->>'periodId')::uuid;select * into bp from public.billing_periods where id=target and project_id=pid for update;if not found then raise exception 'Period unavailable';end if;
 if b->>'action'='review' and bp.state='draft' then update public.billing_periods set state='review' where id=target;
 elsif b->>'action'='publish' and bp.state='review' then update public.billing_periods set state='published' where id=target;insert into public.project_operations(project_id,kind,title,payload,created_by) values(pid,'notice',to_char(bp.month,'YYYY-MM')||' maintenance bills published','{"body":"Your itemized bill is ready in My dues. Pay directly to the project authorised account."}',uid);
 elsif b->>'action'='close' and bp.state='published' then if not coalesce((b->>'reconciled')::boolean,false) or bp.month>date_trunc('month',(now() at time zone 'Asia/Kolkata')::date)::date then raise exception 'Reconcile an actual accounting month before closing';end if;if exists(select 1 from public.project_expense_bills where project_id=pid and period=bp.month and status='pending') or exists(select 1 from public.payment_submissions ps where ps.project_id=pid and ps.status='submitted' and ps.created_at<bp.month+interval '1 month') then raise exception 'Resolve pending bills/payment proofs before closing';end if;res:=private.project_accounts(pid,bp.month)||'{"state":"closed"}'::jsonb;update public.billing_periods set state='closed',snapshot=res where id=target;
 else raise exception 'Invalid billing transition';end if;end if;
 perform private.project_history_add(pid,'billing.'||(b->>'action'),target,'Billing period updated');return jsonb_build_object('id',target);end if;
 if parts[3]='adjustments' then
 target:=(b->>'invoiceId')::uuid;select * into i from public.flat_invoices where id=target and project_id=pid for update;if not found or not private.published_invoice(target) then raise exception 'A published invoice in this project is required';end if;
 eff:=private.op_month(b->>'effectiveMonth');perform private.project_open_day(pid,eff);select month into m from public.billing_periods where id=i.period_id;if eff<m then raise exception 'Correction cannot predate original invoice';end if;
 amount:=private.op_amount(b->>'amount',-100000000,100000000);balance:=(private.invoice_card(i)->>'balance')::bigint;if amount=0 or balance+amount<0 then raise exception 'Correction must change amount and cannot exceed unpaid balance';end if;
 insert into public.invoice_adjustments(project_id,invoice_id,amount,reason,effective_month,actor) values(pid,target,amount,private.op_text(b->>'reason',1000),eff,uid);perform private.project_history_add(pid,'invoice.adjusted',target,'Versioned adjustment in an open month');return jsonb_build_object('ok',true);end if;
 if parts[3]='verify-payment' then
 target:=(b->>'id')::uuid;select * into pay from public.payment_submissions where id=target and project_id=pid for update;if not found then raise exception 'Proof unavailable';end if;
 if pay.status='verified' then return (select to_jsonb(r) from public.project_receipts r where submission_id=target);end if;
 if pay.user_id=uid then raise exception 'Another committee member must verify your own payment';end if;
 if pay.status<>'submitted' or not coalesce((b->>'confirmed')::boolean,false) then raise exception 'Confirm the actual project bank/cash receipt, not just a screenshot';end if;
 d:=(b->>'date')::date;perform private.project_open_day(pid,d);select * into i from public.flat_invoices where id=pay.invoice_id and project_id=pid for update;balance:=(private.invoice_card(i)->>'balance')::bigint;allocated:=least(pay.amount,greatest(balance,0));
 insert into public.project_receipts(project_id,user_id,submission_id,amount,allocated,received_on,verified_by) values(pid,pay.user_id,pay.id,pay.amount,allocated,d,uid) returning id into rid;
 insert into public.project_cash(project_id,fund,amount,paid_on,source,description) values(pid,'general',pay.amount,d,'receipt:'||rid,'Committee-verified resident receipt');update public.payment_submissions set status='verified' where id=pay.id;perform private.project_history_add(pid,'payment.verified',rid,'Verified against project bank/cash records');return jsonb_build_object('id',rid,'amount',pay.amount,'allocated',allocated);end if;
 if parts[3]='apply-credit' then
 target:=(b->>'invoiceId')::uuid;select * into i from public.flat_invoices where id=target and project_id=pid for update;if not found or not private.published_invoice(target) then raise exception 'Published invoice required';end if;
 d:=(now() at time zone 'Asia/Kolkata')::date;perform private.project_open_day(pid,d);amount:=private.op_amount(b->>'amount',1);balance:=(private.invoice_card(i)->>'balance')::bigint;if amount>balance or amount>private.project_credit(pid,i.payer_id) then raise exception 'Insufficient advance or invoice balance';end if;
 insert into public.credit_allocations(project_id,user_id,invoice_id,amount) values(pid,i.payer_id,target,amount);perform private.project_history_add(pid,'credit.applied',target,'Existing advance allocated; no new cash');return jsonb_build_object('ok',true);end if;
 if parts[3]='expenses' then
 m:=private.op_month(b->>'period');perform private.project_open_day(pid,m);if not coalesce(pol->'categories' ? (b->>'category'),false) then raise exception 'Enable this building category in policy first';end if;
 amount:=private.op_amount(b->>'amount',case when nullif(b->>'correctionOf','') is null then 1 else -100000000 end);if amount=0 then raise exception 'Correction must change amount';end if;
 perform private.project_own_attachment(pid,nullif(b->>'attachmentId','')::uuid);perform private.project_own_attachment(pid,nullif(b->>'redactedAttachmentId','')::uuid,true);
 if nullif(b->>'correctionOf','') is not null then select * into bill from public.project_expense_bills where id=(b->>'correctionOf')::uuid and project_id=pid;if not found or bill.details->>'correctionOf' is not null or m<bill.period then raise exception 'Reference an original bill in this project';end if;perform private.op_text(b->>'reason',1000);end if;
 if b->>'category'='Generator diesel' and private.op_amount(b->>'litres',1,100000)*private.op_amount(b->>'rate',1,100000)<>amount then raise exception 'Diesel litres × rate must equal bill amount';end if;
 if nullif(b->>'serviceRequestId','') is not null and (not coalesce((b->>'reviewedService')::boolean,false) or not exists(select 1 from public.service_requests r join public.flats f on f.id=r.flat_id where r.id=(b->>'serviceRequestId')::uuid and f.project_id=pid and r.user_id=uid and r.status='completed')) then raise exception 'Explicitly review your completed project service request';end if;
 insert into public.project_expense_bills(project_id,category,description,period,vendor,bill_date,bill_number,amount,due_date,status,created_by,attachment_id,redacted_attachment_id,details,service_request_id) values(pid,b->>'category',private.op_text(b->>'description',1000),m,private.op_text(b->>'vendor',200),(b->>'billDate')::date,private.op_text(b->>'billNumber',100),amount,(b->>'dueDate')::date,'pending',uid,nullif(b->>'attachmentId','')::uuid,nullif(b->>'redactedAttachmentId','')::uuid,jsonb_build_object('correctionOf',nullif(b->>'correctionOf',''),'reason',b->>'reason','litres',b->>'litres','rate',b->>'rate','meter',left(b->>'meter',300)),nullif(b->>'serviceRequestId','')::uuid) returning id into target;
 perform private.project_history_add(pid,'expense.submitted',target,'Vendor bill accrued; no payment recorded');return jsonb_build_object('id',target);end if;
 if parts[3]='approve-expense' then
 target:=(b->>'id')::uuid;select * into bill from public.project_expense_bills where id=target and project_id=pid for update;if not found then raise exception 'Bill unavailable';end if;if bill.status='approved' then return jsonb_build_object('ok',true);end if;perform private.project_open_day(pid,bill.period);
 if bill.created_by=uid and (coalesce((pol->>'independentReview')::boolean,true) or abs(bill.amount)>=coalesce((pol->>'approvalThreshold')::bigint,0)) then raise exception 'Independent committee review required';end if;
 if bill.details->>'correctionOf' is not null then
 select * into rec from public.project_expense_bills where id=(bill.details->>'correctionOf')::uuid and project_id=pid;
 balance:=rec.amount+coalesce((select sum(amount) from public.project_expense_bills where project_id=pid and status='approved' and details->>'correctionOf'=rec.id::text),0)+bill.amount;
 if balance<coalesce((select sum(amount) from public.project_expense_payments where bill_id=rec.id),0) then raise exception 'Correction would reduce bill below recorded payments';end if;end if;
 update public.project_expense_bills set status='approved',reviewed_by=uid where id=target;perform private.project_history_add(pid,'expense.approved',target,'Approved without recording payment');return jsonb_build_object('ok',true);end if;
 if parts[3]='pay-expense' then
 target:=(b->>'id')::uuid;amount:=private.op_amount(b->>'amount',1);k:=private.op_text(b->>'key',100);
 select * into rec from public.project_expense_payments where project_id=pid and request_key=k;if found then if rec.bill_id<>target or rec.amount<>amount or rec.reference<>b->>'reference' or rec.paid_on<>(b->>'date')::date then raise exception 'Payment retry differs';end if;return to_jsonb(rec);end if;
 select * into bill from public.project_expense_bills where id=target and project_id=pid and status='approved' for update;if not found or bill.details->>'correctionOf' is not null then raise exception 'Pay the original approved vendor bill';end if;
 balance:=bill.amount+coalesce((select sum(amount) from public.project_expense_bills where project_id=pid and status='approved' and details->>'correctionOf'=bill.id::text),0)-coalesce((select sum(amount) from public.project_expense_payments where bill_id=target),0);if amount>balance then raise exception 'Payment exceeds vendor balance';end if;
 d:=(b->>'date')::date;perform private.project_open_day(pid,d);insert into public.project_expense_payments(project_id,bill_id,amount,paid_on,method,reference,actor,request_key) values(pid,target,amount,d,private.op_text(b->>'method',50),private.op_text(b->>'reference',200),uid,k) returning id into rid;
 insert into public.project_cash(project_id,fund,amount,paid_on,source,description) values(pid,'general',-amount,d,'expense:'||rid,'Vendor payment recorded');perform private.project_history_add(pid,'expense.paid',rid,'Actual project payment recorded');return jsonb_build_object('id',rid);end if;
 if parts[3]='cash' then
 d:=(b->>'date')::date;perform private.project_open_day(pid,d);amount:=private.op_amount(b->>'amount',1);k:=private.op_text(b->>'key',100);perform private.op_text(b->>'reason',500);perform private.op_text(b->>'reference',200);
 if coalesce(b->>'action','') not in ('other_receipt','reserve_transfer') or coalesce(b->>'fund','') not in ('general','reserve') or not coalesce((b->>'confirmed')::boolean,false) then raise exception 'Confirm the actual project cash entry and fund';end if;
 ref:=case when b->>'action'='reserve_transfer' then 'transfer:' else 'manual:' end||pid||':'||k;
 select * into rec from public.project_cash where source=ref;if found then if rec.description<>b::text then raise exception 'Cash retry differs';end if;return jsonb_build_object('id',rec.id);end if;
 if b->>'action'='reserve_transfer' then v:=case when b->>'fund'='reserve' then 'general' else 'reserve' end;balance:=case when v='general' then s.opening_cash else s.opening_reserve end+coalesce((select sum(amount) from public.project_cash where project_id=pid and fund=v and paid_on<=d),0);if amount>balance then raise exception 'Transfer exceeds recorded fund balance';end if;
 insert into public.project_cash(project_id,fund,amount,paid_on,source,description) values(pid,v,-amount,d,ref||':from',b::text);end if;
 insert into public.project_cash(project_id,fund,amount,paid_on,source,description) values(pid,b->>'fund',amount,d,ref,b::text) returning id into target;perform private.project_history_add(pid,'cash.'||(b->>'action'),target,b->>'reason');return jsonb_build_object('id',target);end if;
 if parts[3]='operations' then
 kind:=b->>'kind';res:=b->'payload';if coalesce(kind,'') not in ('notice','meeting','asset','template','budget','faq','poll','handover') or coalesce(jsonb_typeof(res),'null')<>'object' or length(res::text)>6000 then raise exception 'Use a valid, concise operation record';end if;
 if kind='poll' and (coalesce(jsonb_typeof(res->'options'),'null')<>'array' or jsonb_array_length(res->'options') not between 2 and 8 or nullif(res->>'ends','') is null or (res->>'ends')::timestamptz<=now() or (select count(distinct trim(x)) from jsonb_array_elements_text(res->'options') x)<>jsonb_array_length(res->'options') or exists(select 1 from jsonb_array_elements_text(res->'options') x where length(trim(x)) not between 1 and 100)) then raise exception 'Poll needs 2–8 distinct choices and a future closing date';end if;
 if kind='asset' and not coalesce(pol->'categories' ? (res->>'category'),false) then raise exception 'Choose configured building equipment';end if;
 if kind='asset' and nullif(res->>'renewal','') is not null then perform (res->>'renewal')::date;end if;
 if kind='budget' then perform private.op_month(res->>'month');perform private.op_amount(res->>'amount');if not coalesce(pol->'categories' ? (res->>'category'),false) then raise exception 'Choose a configured budget category';end if;end if;
 if kind='faq' and (not coalesce((res->>'redacted')::boolean,false) or not exists(select 1 from public.project_questions where id=(res->>'questionId')::uuid and project_id=pid and status='resolved' and visibility='project' and faq_consent)) then raise exception 'FAQ requires a resolved public question, consent and explicit redaction';end if;
 insert into public.project_operations(project_id,kind,title,payload,created_by) values(pid,kind,private.op_text(b->>'title',200),res,uid) returning id into target;perform private.project_history_add(pid,'operation.'||kind,target,'Project-scoped record');return jsonb_build_object('id',target);end if;
 raise exception 'Project action unavailable';end;$$;
revoke all on function public.project_api_internal(text,text,jsonb,jsonb) from public,anon,authenticated;
commit;
